package com.buttercode.mobile;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.media.projection.*;import android.net.Uri;import android.widget.*;import androidx.core.content.FileProvider;import java.io.*;import java.util.*;
public class ScreenNoteActivity extends MainActivity {
 private boolean mic;private static final int AUDIO=81,SCREEN=82,NOTIFICATIONS=83;
 @Override protected void chooseRecording(){if(ScreenRecordingService.active){new AlertDialog.Builder(this).setTitle("Recording in progress").setMessage("Stop and save your recording?").setPositiveButton("Stop recording",(d,w)->startService(new Intent(this,ScreenRecordingService.class).setAction(ScreenRecordingService.STOP))).setNegativeButton("Keep recording",null).show();return;}
  new AlertDialog.Builder(this).setTitle("Record your screen").setMessage("Android will ask which screen or app to share. Recordings stay on this device until you publish. Up to 5 minutes / 25 MB. System audio and a camera bubble are not included in this first Android recorder.").setPositiveButton("Screen + microphone",(d,w)->{mic=true;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},AUDIO);else requestScreen();}).setNeutralButton("Screen only",(d,w)->{mic=false;requestScreen();}).setNegativeButton("Cancel",null).show();
 }
 private void requestScreen(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&!getSharedPreferences("capture",MODE_PRIVATE).getBoolean("notificationsAsked",false)){getSharedPreferences("capture",MODE_PRIVATE).edit().putBoolean("notificationsAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFICATIONS);return;}startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),SCREEN);}
 @Override public void onRequestPermissionsResult(int code,String[] names,int[] results){super.onRequestPermissionsResult(code,names,results);if(code==NOTIFICATIONS){requestScreen();return;}if(code==AUDIO&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)requestScreen();else if(code==AUDIO)Toast.makeText(this,"Microphone permission declined. You can choose Screen only.",Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==SCREEN&&result==RESULT_OK&&data!=null){Intent start=new Intent(this,ScreenRecordingService.class).putExtra("result",result).putExtra("consent",data).putExtra("microphone",mic);startForegroundService(start);Toast.makeText(this,"Recording starts now. Use the recording notification or Record screen to stop.",Toast.LENGTH_LONG).show();}}
 @Override protected void onResume(){super.onResume();String error=getSharedPreferences("capture",MODE_PRIVATE).getString("error",null);if(error!=null){getSharedPreferences("capture",MODE_PRIVATE).edit().remove("error").apply();Toast.makeText(this,error,Toast.LENGTH_LONG).show();}}
 @Override protected void recordings(){File dir=new File(getFilesDir(),"recordings");File[] values=dir.listFiles((d,n)->n.endsWith(".mp4")&&OriginPolicy.recordingId(n.substring(0,n.length()-4))&&!n.equals(ScreenRecordingService.activeFileName));if(values==null||values.length==0){Toast.makeText(this,"No native recordings yet. Stop a recording to save it here.",Toast.LENGTH_LONG).show();return;}Arrays.sort(values,(a,b)->Long.compare(b.lastModified(),a.lastModified()));String[] labels=Arrays.stream(values).map(f->new java.text.SimpleDateFormat("dd MMM HH:mm",Locale.getDefault()).format(new Date(f.lastModified()))+" · "+String.format(Locale.getDefault(),"%.1f MB",f.length()/1000000.0)).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Recordings on this device").setItems(labels,(d,n)->openRecording(values[n])).setNegativeButton("Close",null).show();}
 private void openRecording(File file){new AlertDialog.Builder(this).setTitle("Your recording").setItems(new String[]{"Review and share in ScreenNote","Play recording","Share original MP4","Delete recording"},(d,n)->{String id=file.getName().substring(0,file.getName().length()-4);Uri uri=FileProvider.getUriForFile(this,BuildConfig.APPLICATION_ID+".files",file);if(n==0)web.loadUrl(BuildConfig.APP_ORIGIN+"/?nativeRecording="+id);else if(n==3)new AlertDialog.Builder(this).setMessage("Permanently delete this native recording? Imported copies and published videos are separate.").setPositiveButton("Delete",(a,b)->{if(!file.delete())Toast.makeText(this,"The recording could not be deleted.",Toast.LENGTH_LONG).show();}).setNegativeButton("Keep recording",null).show();else try{Intent intent=n==1?new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"video/mp4"):new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(n==1?intent:Intent.createChooser(intent,"Share recording"));}catch(ActivityNotFoundException e){Toast.makeText(this,"No app can open this video.",Toast.LENGTH_LONG).show();}}).show();}
}
